SELECT category_id, slug, name_zh, name_en, parent_id, sort_order, is_active, banner_url, created_at FROM category
is_active = #{isActive}
ORDER BY sort_order ASC, category_id ASC

SELECT category_id, slug, name_zh, name_en, parent_id, sort_order, is_active, banner_url, created_at
FROM category
WHERE category_id = #{id}

SELECT COUNT(*)
FROM category
WHERE slug = #{name}

    AND category_id != #{excludeId}
